class MethodNotAllowed(Exception):
    """Raised by Router.match when the path exists, but only for other methods. `allowed` is the sorted list of those methods."""

    def __init__(self, allowed):
        super().__init__("method not allowed, use one of: " + ", ".join(allowed))
        self.allowed = allowed


class _Node:
    def __init__(self):
        self.static = {}      # segment text -> child node
        self.param = None     # the child reached through a ":name" segment; one is enough, the names live on the routes
        self.routes = {}      # method -> (handler, parameter names in path order)


def _segments(path):
    path = path.strip("/")                      # a trailing (or leading) slash does not matter
    return path.split("/") if path else []


class Router:
    def __init__(self):
        self._root = _Node()

    def add(self, method, pattern, handler):
        node, names = self._root, []
        for segment in _segments(pattern):
            if segment.startswith(":"):
                names.append(segment[1:])
                if node.param is None:
                    node.param = _Node()
                node = node.param
            else:
                node = node.static.setdefault(segment, _Node())
        node.routes[method] = (handler, names)

    def match(self, method, path):
        segments = _segments(path)
        found = self._find(self._root, segments, 0, [], method)
        if found is not None:
            (handler, names), values = found
            return handler, dict(zip(names, values))
        allowed = set()
        self._collect_methods(self._root, segments, 0, allowed)
        if allowed:
            raise MethodNotAllowed(sorted(allowed))
        return None

    def _find(self, node, segments, depth, values, method):
        """Depth-first search that tries the static child before the parameter child, so the first route found is the most specific."""
        if depth == len(segments):
            return (node.routes[method], list(values)) if method in node.routes else None
        segment = segments[depth]
        child = node.static.get(segment)
        if child is not None:
            found = self._find(child, segments, depth + 1, values, method)
            if found is not None:
                return found
        if node.param is not None and segment:      # a parameter needs a non-empty segment
            values.append(segment)
            found = self._find(node.param, segments, depth + 1, values, method)
            values.pop()
            return found
        return None

    def _collect_methods(self, node, segments, depth, allowed):
        """Every method registered on any route that matches the path, however specific."""
        if depth == len(segments):
            allowed.update(node.routes)
            return
        segment = segments[depth]
        child = node.static.get(segment)
        if child is not None:
            self._collect_methods(child, segments, depth + 1, allowed)
        if node.param is not None and segment:
            self._collect_methods(node.param, segments, depth + 1, allowed)
